"""Input and output format helpers for the Dasel-compatible CLI."""
import csv
import io
import json
try:
    import tomllib
except ImportError:
    tomllib = None


def detect_format(name):
    n=(name or '').lstrip('.')
    return n or 'json'


def load_data(text, fmt='json', flags=None):
    fmt=detect_format(fmt)
    if fmt in ('json','jsonl'):
        if fmt=='jsonl': return [json.loads(line) for line in text.splitlines() if line.strip()]
        return json.loads(text)
    if fmt=='toml': return tomllib.loads(text) if tomllib else parse_toml(text)
    if fmt=='csv':
        reader=csv.reader(io.StringIO(text), delimiter=(flags or {}).get('csv-delimiter', ','), strict=True)
        records=list(reader)
        if not records: return []
        header=records[0]; rows=[]
        for rec in records[1:]:
            if len(rec)!=len(header): raise ValueError('record on line has wrong number of fields')
            rows.append(dict(zip(header,rec)))
        return rows
    if fmt in ('yaml','yml'):
        return parse_yaml(text)
    raise ValueError(f"unsupported input format: {fmt}")


def parse_toml(text):
    root={}; current=root
    def val(s):
        s=s.strip()
        if s.startswith(('\"', "'")):
            try: return json.loads(s) if s.startswith('\"') else s[1:-1]
            except Exception: return s[1:-1]
        if s.lower() in ('true','false'): return s.lower()=='true'
        if s.startswith('[') and s.endswith(']'):
            return [val(x) for x in s[1:-1].split(',') if x.strip()]
        try: return int(s.replace('_',''))
        except Exception: pass
        try: return float(s.replace('_',''))
        except Exception: return s
    for line in text.splitlines():
        line=line.split('#',1)[0].strip()
        if not line: continue
        if line.startswith('[') and line.endswith(']'):
            current=root
            for part in line[1:-1].split('.'):
                current=current.setdefault(part.strip(),{})
            continue
        if '=' in line:
            key,value=line.split('=',1); current[key.strip()]=val(value)
    return root


def parse_yaml(text):
    # Small indentation-based YAML subset, intentionally dependency-free.
    lines=[]
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'): continue
        indent=len(raw)-len(raw.lstrip(' ')); lines.append((indent,raw.strip()))
    if not lines: return None
    def scalar(s):
        s=s.strip()
        if s in ('null','~'): return None
        if s.lower() in ('true','false'): return s.lower()=='true'
        if s.startswith(('"',"'",'[','{')):
            try: return json.loads(s.replace("'",'"') if s.startswith("'") else s)
            except Exception: pass
        try: return int(s)
        except Exception: pass
        try: return float(s)
        except Exception: return s
"""Basic mutation helpers for Dasel-style assignment selectors."""
import json
import re


def _path(text):
    parts = []
    for m in re.finditer(r"(?:^|\.)([A-Za-z_][A-Za-z0-9_-]*)|\[([0-9]+)\]|\[['\"]([^'\"]+)['\"]\]", text.strip()):
        key = next((x for x in m.groups() if x is not None), None)
        if key is None:
            continue
        parts.append(int(key) if m.group(2) is not None else key)
    return parts


def _literal(text, root):
    text = text.strip()
    try:
        return json.loads(text)
    except Exception:
        if text in ("true", "false", "null"):
            return {"true": True, "false": False, "null": None}[text]
        parts = _path(text)
        node = root
        for part in parts:
            node = node[part]
        return node


def assign(data, query):
    """Apply a simple `path = literal` selector, returning (selected, root)."""
    m = re.fullmatch(r"\s*(.*?)\s*=\s*(.*?)\s*", query, re.S)
    if not m:
        raise ValueError("not a simple assignment")
    parts = _path(m.group(1))
    if not parts:
        raise ValueError("empty assignment path")
    value = _literal(m.group(2), data)
    node = data
    for part in parts[:-1]:
        node = node[part]
    node[parts[-1]] = value
    return value, data

