def _path(text):
    parts = []
    for m in re.finditer(r"(?:^|\.)([A-Za-z_][A-Za-z0-9_-]*)|\[([0-9]+)\]|\[['\"]([^'\"]+)['\"]\]", text.strip()):
        key = next((x for x in m.groups() if x is not None), None)
        if key is None:
            continue
        parts.append(int(key) if m.group(2) is not None else key)
    return parts


def _literal(text, root):
    text = text.strip()
    try:
        return json.loads(text)
    except Exception:
        if text in ("true", "false", "null"):
            return {"true": True, "false": False, "null": None}[text]
        parts = _path(text)
        node = root
        for part in parts:
            node = node[part]
        return node


