"""Input and output format helpers for the Dasel-compatible CLI."""
import csv
import configparser
import io
import json
import re
import xml.etree.ElementTree as ET
try:
    import tomllib
except ImportError:
    tomllib = None


def detect_format(name):
    n=(name or '').lstrip('.')
    return n or 'json'


def load_data(text, fmt='json', flags=None):
    fmt=detect_format(fmt)
    if fmt=='json':
        return None if not text.strip() else parse_json(text)
    if fmt=='toml': return tomllib.loads(text) if tomllib else parse_toml(text)
    if fmt=='xml': return parse_xml(text, flags or {})
    if fmt=='kdl': return parse_kdl(text)
    if fmt=='ini': return parse_ini(text)
    if fmt=='hcl': return parse_hcl(text)
    if fmt=='csv':
        reader=csv.reader(io.StringIO(text), delimiter=(flags or {}).get('csv-delimiter', ','), strict=True)
        records=list(reader)
        if not records: return None
        header=records[0]; rows=[]
        for rec in records[1:]:
            if len(rec)!=len(header): raise ValueError('record on line has wrong number of fields')
            rows.append(dict(zip(header,rec)))
        return rows
    if fmt == 'yaml':
        return parse_yaml(text)
    raise ValueError(f"unsupported input format: {fmt}")


def parse_json(text):
    # The reference decoder accepts a few common trailing-comma/empty-field
    # forms that Python's strict JSON parser rejects.
    cleaned=re.sub(r',\s*([}\]])',r'\1',text)
    cleaned=re.sub(r'"([^"\\]*(?:\\.[^"\\]*)*)"\s*:\s*(?=[,}])', '', cleaned)
    try:
        return json.loads(cleaned)
    except json.JSONDecodeError as exc:
        stripped=text.rstrip()
        if stripped.startswith('"') and not stripped.endswith('"'):
            detail='json: string unexpected end of JSON input'
        elif stripped.startswith('{') and (exc.pos >= len(stripped)-1 or stripped=='{'):
            detail='could not decode object: EOF'
        elif stripped.startswith('{') and exc.pos < len(stripped):

        elif stripped.startswith('{') and exc.pos < len(stripped):
            ch=stripped[exc.pos]
            detail=f'could not decode object: json: invalid character {ch} as token'
        elif stripped=='foo':
            detail='json: invalid character o as bool(false)'
        else:
            detail=f'json: invalid character {stripped[exc.pos:exc.pos+1] or "EOF"} as token'
        raise ValueError('error reading input: '+detail)


def parse_hcl(text):
    import re
    root={}; stack=[root]
    def value(s):
        s=s.strip().rstrip(',')
        if s.startswith('"'):
            try:return json.loads(s)
            except Exception:return s.strip('"')
        if s in ('true','false'):return s=='true'
        if s.startswith('[') and s.endswith(']'):
            try:return json.loads(s)
            except Exception:return [value(x) for x in s[1:-1].split(',') if x.strip()]
        try:return int(s)
        except Exception:pass
        try:return float(s)
        except Exception:return s
    for raw in text.splitlines():
