def dump_ini(value):
    if not isinstance(value,dict): raise ValueError('ini can only represent map values')
    lines=[]
    for key,val in value.items():
        if isinstance(val,dict): continue
        if isinstance(val,list): raise ValueError('ini writer cannot represent slice values directly; consider using nested sections')
        if val is not None: lines.append(f'{key} = {str(val).lower() if isinstance(val,bool) else val}')
    tables=[(key,val) for key,val in value.items() if isinstance(val,dict)]
    for key,val in tables:
        if lines: lines.append('')
        lines.append(f'[{key}]')
        for k,v in val.items():
            if isinstance(v,list): raise ValueError('ini writer cannot represent slice values directly; consider using nested sections')
            if v is not None: lines.append(f'{k} = {str(v).lower() if isinstance(v,bool) else v}')
    return '\n'.join(lines)


